cd /app && cat > blast2.py <<'EOF'
import urllib.request,urllib.parse,time,sys,re
seqs={"heavy":"QVQLQQSAAELARPGASVKMSCKASGYSFTTYTIHWVKQRPGQGLEWIGYINPSSGYAAYNQNFKDETTLTADPSSSTAYMELNSLTSEDSAVYYCAREKFYGYDYWGQGATLTVSS",
"light":"DVLMTQIPLSLPVSLGDQASISCRSSQSIVHRNGNTYLEWYLLKPGQSPKLLIYKVSNRFSGVPDRFSGSGSGTDFTLKISRVEAEDLGVYYCFQGSHVPYTFGGGTKLEIR"}
url="https://blast.ncbi.nlm.nih.gov/Blast.cgi"
rids={}
for name,q in seqs.items():
    params={"CMD":"Put","PROGRAM":"blastp","DATABASE":"nr","QUERY":q,"HITLIST_SIZE":"50"}
    r=urllib.request.urlopen(url,urllib.parse.urlencode(params).encode(),timeout=60).read().decode()
    rids[name]=re.search(r"RID = (\S+)",r).group(1)
    print(name,rids[name],flush=True)
done=set()
for i in range(60):
    time.sleep(15)
    for name,rid in rids.items():
        if name in done: continue
        s=urllib.request.urlopen(url+"?CMD=Get&FORMAT_OBJECT=SearchInfo&RID="+rid,timeout=60).read().decode()
        m=re.search(r"Status=(\w+)",s); st=m.group(1) if m else "?"
        if st=="READY":
            done.add(name)
            res=urllib.request.urlopen(url+"?CMD=Get&FORMAT_TYPE=Text&RID="+rid+"&DESCRIPTIONS=50&ALIGNMENTS=0",timeout=120).read().decode()
            print("==========",name,"==========")
            for line in res.splitlines():
                if line and ('antibody' in line.lower() or 'Fab' in line or 'immunoglob' in line.lower() or 'chain' in line.lower() or '%' in line):
                    print(line)
    if len(done)==len(rids): break
EOF
python3 blast2.py 2>&1 | tail -80
